def place_services(apps, schema_editor):
    """Puts each service where the site showed it. Card wording changed in Site settings is carried over as it was."""
    Service = apps.get_model('services', 'Service')
    SiteSettings = apps.get_model('home', 'SiteSettings')
    settings = SiteSettings.objects.filter(pk=1).first()
    changed = (settings.page_text or {}) if settings else {}

    for part, (slug, label) in BOARD.items():
        service = Service.objects.filter(slug=slug).first()
        if service and not service.board_part and not Service.objects.filter(board_part=part).exists():
            service.board_part = part
            service.board_label = label
            service.save(update_fields=['board_part', 'board_label'])

    for card, (slug, icon, track, title, text, tags) in CARDS.items():
        service = Service.objects.filter(slug=slug).first()
        if not service or service.home_card or Service.objects.filter(home_card=card).exists():
            continue
        said = lambda field, standard: (changed.get(f'home_cap{card}_{field}') or '').strip() or standard
        service.home_card = card
        service.home_card_icon = icon
        service.home_card_track = said('track', track)
        service.home_card_title = said('title', title)
        service.home_card_text = said('text', text)
        service.home_card_tags = said('tags', tags)
        service.save(update_fields=['home_card', 'home_card_icon', 'home_card_track', 'home_card_title', 'home_card_text', 'home_card_tags'])


